"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[2560],{79277(s){s.exports=JSON.parse('{"ko_kr":{"ZombiLine":{"success_critical":"\uc131\uacf5(\ud06c\ub9ac\ud2f0\uceec)","success_fumble":"\uc131\uacf5(\ud38c\ube14)","success":"\uc131\uacf5","failure_fumble":"\uc2e4\ud328(\ud38c\ube14)","failure":"\uc2e4\ud328","SST":{"name":"\uc2a4\ud2b8\ub808\uc2a4 \uc99d\uc0c1\ud45c","type":"1D10","items":["[\ubd84\ub178] \uac00\uc7a5 \uac00\uae4c\uc774 \uc788\ub294 \uc801\uc744 \uacf5\uaca9(\uc131\uacf5\ub960 +20%)\ud569\ub2c8\ub2e4. \uac00\uae4c\uc774 \uc801\uc774 \uc5c6\ub294 \uacbd\uc6b0, \ub204\uad70\uac00\uc758 \uc2a4\ud2b8\ub808\uc2a4\ub97c +1\uc2dc\ud0b5\ub2c8\ub2e4. / \uc124\uba85: \uba38\ub9ac\uc5d0 \ud53c\uac00 \ubab0\ub824 \ub204\uad70\uac00\uc5d0\uac8c \ud654\ub97c \ud130\ud2b8\ub9bd\ub2c8\ub2e4.","[\ub3c4\ud53c] \ub099\ud558\ud558\ub354\ub77c\ub3c4 \uc801\uc5d0\uac8c\uc11c \ub3c4\ub9dd\uce58\ub824 \uc774\ub3d9\ud569\ub2c8\ub2e4. \uc8fc\ubcc0\uc5d0 \uc801\uc774 \uc5c6\ub294 \uacbd\uc6b0, \ud604\uc2e4\ub3c4\ud53c\ub97c \ud558\ub824 \ud569\ub2c8\ub2e4. / \uc124\uba85: \uacac\ub51c \uc218 \uc5c6\uac8c \ub418\uc5b4 \ub3c4\ub9dd\uce69\ub2c8\ub2e4.","[\ud658\uc0c1] \uc804\ud22c \uc911\uc5d0\ub294 \u300c\ud589\ub3d9\ubc29\uce58(\uc804AP)\u300d\ub97c \ud569\ub2c8\ub2e4. \uc804\ud22c \uc774\uc678\uc758 \uacbd\uc6b0, \ud658\uc0c1\uc744 \ubcf4\uba70 \uc6c3\uc74c\uc744 \ud758\ub9bd\ub2c8\ub2e4. / \uc124\uba85: \uc790\uc2e0\uc774 \uafc8\uafb8\ub294 \ud658\uc0c1\uc744 \ubd05\ub2c8\ub2e4.","[\uc808\uaddc] \uc804\ud22c \uc911\uc5d0\ub294 \ube44\uba85\uc744 \uc9c0\ub974\uba70 \u300c\uc8fc\ubaa9\uc744 \ubaa8\uc740\ub2e4(2AP)\u300d\ub97c \ud569\ub2c8\ub2e4. \uc804\ud22c \uc774\uc678\uc758 \uacbd\uc6b0, \ubb34\uc758\ubbf8\ud55c \uc18c\ub9ac\ub97c \uc9c0\ub985\ub2c8\ub2e4. / \uc124\uba85: \uc0dd\uac01\uc5c6\uc774 \ube44\uba85\uc744 \uc9c0\ub985\ub2c8\ub2e4.","[\uc790\ud574] \uc2a4\uc2a4\ub85c \u3010\uc0c1\ucc98\u3011\ub97c \uc785\uc2b5\ub2c8\ub2e4. \uc804\ud22c \uc911\uc5d0\ub294 \u300c\uc790\ud574\ud589\uc704(1AP)\u300d\ub85c \uc2a4\uc2a4\ub85c\uc5d0\uac8c \u3010\uc0c1\ucc98\u3011\ub97c \uc785\ud799\ub2c8\ub2e4. / \uc124\uba85: \uc0dd\uac01\uc5c6\uc774 \uc790\uc2e0\uc5d0\uac8c \uc0c1\ucc98\ub97c \uc785\ud799\ub2c8\ub2e4.","[\ubd88\uc548] \ub204\uad70\uac00\uc758 \uc2a4\ud2b8\ub808\uc2a4\ub97c 1 \uc62c\ub9bd\ub2c8\ub2e4. \uadfc\ucc98\uc5d0 \uc544\ubb34\ub3c4 \uc5c6\ub294 \uacbd\uc6b0, \uc6b8\uc74c\uc744 \ud130\ud2b8\ub9bd\ub2c8\ub2e4. / \uc124\uba85: \ubd88\uc548\ud574\uc838 \uc4f8\ub370\uc5c6\ub294 \ub9d0\uc744 \uc9c0\uaec4\uc785\ub2c8\ub2e4.","[\uae30\ud53c] \uadf8 \uc790\ub9ac\uc5d0\uc11c \uac00\uc7a5 \uac00\uae4c\uc774 \uc788\ub294 \ub300\uc0c1\uc5d0\uac8c \u300c\ub3cc(1AP)\u300d\uc744 \ub358\uc9d1\ub2c8\ub2e4. \uadf8\uac8c \ubd88\uac00\ub2a5\ud55c \uacbd\uc6b0, \u3010\ub118\uc5b4\uc9d0\u3011\uc0c1\ud0dc\uac00 \ub429\ub2c8\ub2e4. / \uc124\uba85: \ud610\uc624\uac10\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc744 \uac70\ubd80\ud569\ub2c8\ub2e4.","[\ud3ed\uc8fc] \uac00\uc7a5 \uac00\uae4c\uc774 \uc788\ub294 \uc801\uc5d0\uac8c \uacf5\uaca9\uc744 \uac00\ud569\ub2c8\ub2e4. \uac00\uae4c\uc774 \uc801\uc774 \uc5c6\ub294 \uacbd\uc6b0 \uc8fc\ubcc0\uc758 \uc758\uacac\uc744 \ub4e3\uc9c0 \uc54a\uace0 \uc81c\uba4b\ub300\ub85c \ud589\ub3d9\uc744 \ud569\ub2c8\ub2e4. / \uc124\uba85: \ub0c9\uc815\uc744 \ucc3e\uc9c0 \ubabb\ud558\uace0 \uc81c\uba4b\ub300\ub85c \ud589\ub3d9\ud569\ub2c8\ub2e4.","[\ud63c\ub780] \uac00\uae4c\uc774 \uc788\ub294 \ubb34\uc791\uc704 \ub300\uc0c1\uc5d0\uac8c \uaca9\ud22c\ub85c \uacf5\uaca9\uc744 \uac00\ud569\ub2c8\ub2e4. \uadf8\uac8c \ubd88\uac00\ub2a5\ud55c \uacbd\uc6b0 \u300c\ud589\ub3d9\ubc29\uce58(\uc804AP)\u300d\ub97c \ud569\ub2c8\ub2e4. / \uc124\uba85: \uc138\uc0c1 \ubaa8\ub4e0 \uac83\uc774 \uc801\uc73c\ub85c \ubcf4\uc5ec \uacf5\uaca9\ud569\ub2c8\ub2e4.","[\uac1c\uc548] \uc2a4\ud2b8\ub808\uc2a4\uac00 0\uae4c\uc9c0 \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4. \ub2f9\uc2e0\uc740 \uad50\uc870\uac00 \ub418\uc5b4 \uad50\uc758\ub97c \ud55c\uac00\uc9c0 \uc815\ud574 \u300c\ud3ec\uad50\u300d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \uc99d\uc0c1\uc774 \ub098\uc62c \ub54c\uae4c\uc9c0 \ud6a8\uacfc\uac00 \uc9c0\uc18d\ub429\ub2c8\ub2e4. / \uc124\uba85: \uc880\ube44\ud22c\uc131\uc774 \uc138\uc0c1\uc758 \uc9c4\ub9ac\ub97c \ubcf4\uc558\uc2b5\ub2c8\ub2e4."]},"IT":{"name":"\uc2dd\uc7ac\ub8cc \ud45c","items":{"raw":"\uc2e0\uc120 \uc2dd\uc7ac\ub8cc","suspicious":"\uc218\uc0c1\ud55c \uc2dd\uc7ac\ub8cc","dangerous":"\uc704\ud5d8\ud55c \uc2dd\uc7ac\ub8cc"}}}}}')}}]);